// Network-first service worker: online you always get the latest files (and the cache is refreshed); offline the cache answers.
// (v1 was cache-first and never noticed edited files, so a refresh kept showing the old app.)
// VERSION and the list below are generated by `npm run sw`; do not edit them by hand. A new VERSION is what makes phones update.
// PRECACHE-START
const VERSION = 'aa89a998c3dd';
const PRECACHE = [
  "./",
  "css/app.css",
  "css/army.css",
  "css/attack.css",
  "css/game.css",
  "css/strats.css",
  "data/adepta-sororitas/datasheets.json",
  "data/adepta-sororitas/detachments.json",
  "data/adepta-sororitas/effects.json",
  "data/core/abilities.json",
  "data/core/missions.json",
  "data/core/stratagems.json",
  "data/emperors-children/datasheets.json",
  "data/emperors-children/detachments.json",
  "data/emperors-children/effects.json",
  "data/emperors-children/game.json",
  "data/factions.json",
  "data/orks/datasheets.json",
  "data/orks/detachments.json",
  "data/orks/effects.json",
  "data/orks/example-roster.json",
  "data/orks/game.json",
  "icon.svg",
  "index.html",
  "js/attack-setup.js",
  "js/data.js",
  "js/dom.js",
  "js/engine/attack.js",
  "js/engine/collect.js",
  "js/engine/dice.js",
  "js/engine/effects.js",
  "js/engine/parse.js",
  "js/engine/stratagems.js",
  "js/game.js",
  "js/main.js",
  "js/roster.js",
  "js/scoring.js",
  "js/share.js",
  "js/store.js",
  "js/ui/army.js",
  "js/ui/attack.js",
  "js/ui/datasheet.js",
  "js/ui/game.js",
  "js/ui/score.js",
  "js/ui/strat-actions.js",
  "js/ui/strats.js",
  "js/ui/target.js",
  "manifest.webmanifest"
];
// PRECACHE-END
const CACHE = `dicehelper-${VERSION}`;   // older caches are dropped on activate
const DEV = ['localhost', '127.0.0.1'].includes(self.location.hostname); // development must never be stale

self.addEventListener('install', e => {
  if (DEV) return;
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (DEV || req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  e.respondWith(fetch(req, { cache: 'no-cache' }).then(res => {
    if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  }).catch(() => caches.match(req, { ignoreSearch: true }).then(hit => hit || Response.error())));
});
